package com.chilicraft.quest;
import com.chilicraft.api.*; import org.bukkit.Bukkit; import org.bukkit.Material; import org.bukkit.plugin.RegisteredServiceProvider; import org.bukkit.plugin.java.JavaPlugin; import java.io.File; import java.util.*;
public final class ChiliQuestPlugin extends JavaPlugin { private ChiliCraftAPI api; private QuestSettings settings; private QuestContentLoader loader; private QuestService service; private EventHandler events,reload; private static final List<String> EVENT_NAMES=List.of("demon.mob_killed","soul.relic_gained","martial.arena_win","martial.realm_up","adventure.boss_killed","adventure.dungeon_clear","adventure.expedition_result","season.special_day"); public void onEnable(){saveDefaultConfig();saveResource("chapters.yml",false);RegisteredServiceProvider<ChiliCraftAPI> r=getServer().getServicesManager().getRegistration(ChiliCraftAPI.class);if(r==null){getServer().getPluginManager().disablePlugin(this);return;}api=r.getProvider();settings=new QuestSettings(this);settings.refresh();api.registerModuleConfig("cc-quest",new LiveModuleConfig(this));loader=new QuestContentLoader(new File(getDataFolder(),"chapters.yml"),getLogger());if(!loader.reload()){getServer().getPluginManager().disablePlugin(this);return;}service=new QuestService(api,new QuestRepository(this,api),settings,loader);QuestGui gui=new QuestGui(service,settings);QuestCommand cmd=new QuestCommand(this,service,gui,settings);events=(n,d)->service.event(n,d);for(String n:EVENT_NAMES)api.subscribe(n,events);api.registerMenuEntry(new ModuleMenuEntry("quest","任务",MenuCategory.PROGRESSION,Material.WRITTEN_BOOK,10,Set.of("chilicraft.quest.use"),Set.of("chilicraft.quest.admin"),"旅途手册",()->true,gui::open,p->p.sendMessage(settings.message("help","打开旅途手册。"))));api.registerCommandRoute(new ModuleCommandRoute("quest",Set.of(),Set.of("chilicraft.quest.use"),Set.of("chilicraft.quest.admin"),cmd::execute,cmd::complete));reload=(n,d)->reloadQuest();api.subscribe("core.reload",reload);} void reloadQuest(){reloadConfig();settings.refresh();loader.reload();service.reload(loader);} public void onDisable(){if(service!=null)service.shutdown();if(api!=null){for(String n:EVENT_NAMES)api.unsubscribe(n,events);if(reload!=null)api.unsubscribe("core.reload",reload);api.unregisterCommandRoute("quest");api.unregisterMenuEntry("quest");}api=null;service=null;loader=null;settings=null;}}
